// active camera/pet points for the chosen layout (drive the preview aids)
CAM_ACT = (LAYOUT == "front") ? [0, CAM_F_Y, CAM_F_Z] : [0, WEDGE_Y, PED_TOP + BM_LIFT];
PET_ACT = (LAYOUT == "front") ? [0, PETF_Y, PETF_Z]   : [0, PET_FACE_Y, PET_FACE_Z];

// ============================================================================
// CAMERA POD  --  the OV5640 RELOCATED off the board's back onto a 30cm FFC.
// ----------------------------------------------------------------------------
// The -C's camera is a bare OV5640 module that PLUGS into a 24-pin 0.5mm DVP
// connector (schematic J2, "0.5-24pin-cam"). Unplugging it and running a 30cm
// FFC + coupler lets the camera live anywhere -- so it no longer has to ride the
// board. The board stays on the pedestal as the SCREEN; this pod carries the
// lens out over the bowl and aims it at the pet.
//
// WHAT THIS PART IS: a small open-back enclosure that captures the bare module.
// It is deliberately built to the WIDE-ANGLE / MAX envelope, because the exact
// module was not calipered -- generic 24-pin OV5640 modules run 12.5..14.0mm
// square with a wide-angle barrel up to 14mm dia standing up to ~11mm proud.
// Sized to the top of that range, a smaller real part just sits looser and is
// taken up by adhesive; sized to the middle, a big one would not fit at all.
//
// RETENTION, and why there are no clamp tabs: with a 14mm barrel on a 14mm PCB
// the barrel eats almost the whole front face, so there is no front bezel to
// grab -- only the four PCB CORNERS (corner radius 9.9 > barrel radius 7.0) show.
// A rigid tab would also have to guess the PCB thickness, which varies. So the
// scheme is the one the module actually wants: the PCB drops into the pocket
// (located in X/Y by the walls), its front face lands on the FRONT-STOP LEDGE
// (the front plate, which the barrel pokes through), and a bead of silicone from
// the open back holds it. Nothing rigid touches the barrel -- which matters if it
// is an AUTO-FOCUS module, whose barrel is a moving VCM element and jams if
// pressed. The lens tip stands proud of the front plate, so the pod never
// vignettes even a 120deg cone.
POD_PCB     = 14.0;   // max square module PCB (wide-angle OV5640 envelope)
POD_FIT     = 0.6;    // per-axis pocket clearance (MJF; FDM takes it up in glue)
POD_WALL    = 2.5;    // pocket wall
POD_FRONT_T = 2.0;    // front plate = the front-stop ledge the PCB seats on
POD_DEPTH   = 6.0;    // pocket depth behind the ledge (PCB + rear components)
POD_BARREL  = 15.0;   // front aperture -- clears a 14mm barrel, lens pokes out
POD_FFC_W   = 13.0;   // FFC exit slot (24p @0.5 tail is 12.5 wide)
POD_FFC_H   = 2.5;    // FFC slot height
POD_EAR_L   = 8.0;    // side mounting ear reach (carries 2x M3 to the arm)
POD_EAR_T   = 3.0;    // ear thickness
POD_OUT     = POD_PCB + POD_FIT + 2*POD_WALL;   // 19.6 outer square
POD_H       = POD_FRONT_T + POD_DEPTH;          // 8.0 body height (front->back)
POD_POCK    = POD_PCB + POD_FIT;                // 14.6 pocket

// Local frame: the lens looks along -Z, the open back faces +Z, the FFC leaves
// through the +Y wall. The caller translates + tilts it to aim.
module cam_pod() {
    difference() {
        union() {
            // solid body
            translate([-POD_OUT/2, -POD_OUT/2, 0]) cube([POD_OUT, POD_OUT, POD_H]);
            // two side ears at the back, out of the -Z field of view. Inset 1mm
            // into the body so they FUSE (a coplanar touch reads as a 2nd solid).
            for (s = [-1, 1])
                translate([s > 0 ? POD_OUT/2 - 1 : -POD_OUT/2 - POD_EAR_L + 1,
                           -POD_OUT/2, POD_H - POD_EAR_T])
                    cube([POD_EAR_L + 1, POD_OUT, POD_EAR_T]);
        }
        // PCB pocket, open at the back (+Z)
        translate([-POD_POCK/2, -POD_POCK/2, POD_FRONT_T])
            cube([POD_POCK, POD_POCK, POD_DEPTH + 0.2]);
        // barrel aperture through the front plate
        translate([0, 0, -0.1]) cylinder(d = POD_BARREL, h = POD_FRONT_T + 0.2, $fn = 48);
        // FFC exit slot through the +Y wall
        translate([-POD_FFC_W/2, POD_POCK/2 - 0.1, POD_FRONT_T + 1])
            cube([POD_FFC_W, POD_WALL + 0.4, POD_FFC_H]);
        // M3 clearance through each ear
        for (s = [-1, 1])
            translate([s * (POD_OUT/2 + POD_EAR_L/2), 0, POD_H - POD_EAR_T - 0.1])
                cylinder(d = 3.4, h = POD_EAR_T + 0.2, $fn = 24);
    }
}

// Proposed placement (PREVIEW ONLY -- the mast that would carry it is not cut
