// ============================================================================
// CAMERA RISER  --  the gantry that CARRIES the pod, printed as part of the
// pedestal (mount_back). It rides the pedestal's existing four M3 bolts and
// adds NO base-plate holes.
// ----------------------------------------------------------------------------
// The pod's back-rim pad ends up high and forward -- world ~[0,-91.6,55.2],
// out over the top of the screen. A mast cannot rise straight up to it (the
// board is underneath) and cannot rise behind the screen (that would block the
// owner's view). So the carrier is a GANTRY: two legs stand OUTBOARD of the
// cradle (past its 50.35mm half-width), then two arms sweep up-and-forward OVER
// the screen top and converge on the pod pad at the centreline. The centre is
// left open both ways -- the owner sees the screen between the legs, the lens
// sees the bowl under the boom. The legs overlap the existing pedestal posts at
// the base (start below the post top) so the whole thing fuses into one solid.
RIS_X    = 59;                 // leg centre X -- outboard of the cradle (50.35)
RIS_W    = 12;                 // leg width (X)
RIS_D    = 14;                 // leg depth (Y)
RIS_Y    = -60;                // leg centre Y -- behind the board's rear edge -63.3
RIS_BOT  = PED_TOP - 4 - 12;   // start 12mm inside the post tops so volumes merge
RIS_TOP  = 50;                 // leg top z
RIS_ARM  = 11;                 // boom arm cross-section
RIS_PAD_T = 6;                 // pad plate thickness behind the pod ears
RIS_PILOT = 2.6;              // M3 self-tap pilot in the pad (screws come up
                              // through the pod's 3.4 ear holes from below)
// Pod back-rim pad centre in WORLD coords: translate(POD_AT)*rot([TILT])*[0,0,POD_H]
RIS_PAD_C = [0,
             POD_AT[1] - POD_H * sin(POD_TILT),
             POD_AT[2] + POD_H * cos(POD_TILT)];

module cam_riser() {
    color("DimGray") {
        // two legs, standing OUTBOARD of the board, clear of the cradle wall
        for (s = [-1, 1])
            translate([s * RIS_X - RIS_W/2, RIS_Y - RIS_D/2, RIS_BOT])
                cube([RIS_W, RIS_D, RIS_TOP - RIS_BOT]);
        // base gusset tying each leg back to its pedestal post. Lives ONLY in the
        // sub-cradle zone (z <= -22, the board starts at PED_TOP=-20) so it can
        // reach inboard to the post at X=+/-48 without touching the cradle above.
        for (s = [-1, 1])
            hull() {
                translate([s * 48, -63, PED_TOP - 4 - 6])
                    cube([12, 10, 8], center = true);   // over the post top
                translate([s * RIS_X, RIS_Y, RIS_BOT + 5])
                    cube([RIS_W, RIS_D, 10], center = true);  // leg base
            }
        // two slender boom struts: each hulls from the INNER-top corner of a leg
        // up-and-forward to the pod pad, forming a light triangulated A-frame
        // that lands on the centreline over the screen (no heavy wedge, and more
        // clearance over the board top than a full-section arm would give)
        for (s = [-1, 1])
            hull() {
                translate([s * (RIS_X - RIS_W/2 + RIS_ARM/2), RIS_Y, RIS_TOP - RIS_ARM/2])
                    cube([RIS_ARM, RIS_D, RIS_ARM], center = true);
                translate(RIS_PAD_C) rotate([POD_TILT, 0, 0])
                    cube([RIS_ARM, RIS_ARM, RIS_ARM], center = true);
            }
    }
    // the pad plate the pod bolts to, built in the pod's tilted frame so its
    // mating face is parallel to the pod back and the pilots line up with the
    // ears (holes at X = +/- (POD_OUT/2 + POD_EAR_L/2))
    EAR_X = POD_OUT/2 + POD_EAR_L/2;
    color("DimGray")
        translate(POD_AT) rotate([POD_TILT, 0, 0])
            difference() {
                translate([-(EAR_X + 4), -RIS_ARM/2, POD_H - 0.2])
                    cube([2*(EAR_X + 4), RIS_ARM, RIS_PAD_T + 0.2]);
                for (s = [-1, 1])
                    translate([s * EAR_X, 0, POD_H - 0.3])
                        cylinder(d = RIS_PILOT, h = RIS_PAD_T + 1, $fn = 24);
            }
}

