// ============================================================================
// CAMERA MAST  --  the slim front post that CARRIES the pod, a SEPARATE printed
// part that bolts to base_front with two M3 (holes drilled in base_plate_solid
// at the same XY). It rises from the base floor at the front-right corner, up
// past the front bowl rim, to the pod head.  Decoupled from the pedestal: the
// pedestal reverts to its plain form, and the owner-facing screen no longer
// shares any structure with the camera.
// ----------------------------------------------------------------------------
// The foot is placed OUTSIDE the bowl locating ring (r71): at [60,-178] it is
// 82mm from the bowl centre, clear.  A single vertical post (no gantry) hulls
// up to a pad built in the pod's tilted frame, so the pad face is parallel to
// the pod back and the two pilots line up with the pod ears.
MAST_X      = POD_AT[0];        // post centre X (front-right corner)
MAST_Y      = POD_AT[1];        // post centre Y (in front of the bowl rim)
MAST_BOTZ   = STAND_BASE_Z;     // rests on the base pocket floor top (-122)
MAST_W      = 14;               // post cross-section (X)
MAST_D      = 18;               // post cross-section (Y)
MAST_PAD_T  = 6;                // pad plate thickness behind the pod ears
MAST_PILOT  = 2.6;              // M3 self-tap pilot in the pad
MAST_BOLT_DY = 11;              // 2x M3 base bolts, +/- in Y through the foot

module cam_mast() {
    EAR_X = POD_OUT/2 + POD_EAR_L/2;
    color("DimGray") difference() {
        union() {
            // vertical post: foot on the base floor hulled up to just under the
            // pod pad (in the pod's tilted frame, so it meets the pad squarely)
            hull() {
                translate([MAST_X - MAST_W/2, MAST_Y - MAST_D/2, MAST_BOTZ])
                    cube([MAST_W, MAST_D, 3]);
                translate(POD_AT) rotate([0, 0, POD_YAW]) rotate([POD_PITCH, 0, 0])
                    translate([-MAST_W/2, -MAST_D/2, POD_H - 3])
                        cube([MAST_W, MAST_D, 3]);
            }
            // the pad the pod bolts onto, in the pod's tilted frame, with two
            // pilots aligned to the ears (holes at X = +/- (POD_OUT/2+POD_EAR_L/2))
            translate(POD_AT) rotate([0, 0, POD_YAW]) rotate([POD_PITCH, 0, 0])
                difference() {
                    translate([-(EAR_X + 4), -POD_OUT/2, POD_H - 0.2])
                        cube([2*(EAR_X + 4), POD_OUT, MAST_PAD_T + 0.2]);
                    for (s = [-1, 1])
                        translate([s * EAR_X, 0, POD_H - 0.3])
                            cylinder(d = MAST_PILOT, h = MAST_PAD_T + 1, $fn = 24);
                }
        }
        // two M3 clearance holes down through the foot into the base
        for (s = [-1, 1])
            translate([MAST_X, MAST_Y + s * MAST_BOLT_DY, MAST_BOTZ - 0.1])
                cylinder(d = 3.4, h = 14, $fn = 24);
    }
}

