module cam_mast() {
    EAR_X = POD_OUT/2 + POD_EAR_L/2;
    color("DimGray") difference() {
        union() {
            // two legs: each foot on the base floor hulled up to the pod pad,
            // meeting at the centre (they overlap there and fuse into one solid)
            for (s = [-1, 1])
                hull() {
                    translate([s * YOKE_FX - YOKE_W/2, YOKE_FY - YOKE_D/2, YOKE_BOTZ])
                        cube([YOKE_W, YOKE_D, 3]);
                    translate(POD_AT) rotate([0, 0, POD_YAW]) rotate([POD_PITCH, 0, 0])
                        translate([-YOKE_W/2, -YOKE_D/2, POD_H - 3])
                            cube([YOKE_W, YOKE_D, 3]);
