                }
        }
        // one M3 clearance hole down through each foot into the base
        for (s = [-1, 1])
            translate([s * YOKE_FX, YOKE_FY, YOKE_BOTZ - 0.1])
                cylinder(d = 3.4, h = 14, $fn = 24);
    }
}

