import re
def stats(fn):
    verts=[]; tris=[]; cur=[]
    for line in open(fn):
        m=re.match(r'\s*vertex\s+(\S+)\s+(\S+)\s+(\S+)',line)
        if m:
            cur.append(tuple(map(float,m.groups())))
            if len(cur)==3: tris.append(cur); verts.extend(cur); cur=[]
    vol=0.0
    for a,b,c in tris:
        vol += (a[0]*(b[1]*c[2]-b[2]*c[1]) - a[1]*(b[0]*c[2]-b[2]*c[0]) + a[2]*(b[0]*c[1]-b[1]*c[0]))/6.0
    xs=[v[0] for v in verts]; ys=[v[1] for v in verts]; zs=[v[2] for v in verts]
    return abs(vol)/1000.0, (max(xs)-min(xs), max(ys)-min(ys), max(zs)-min(zs))
for f in ["velapaw_cam_mast_x1","velapaw_base_front_x1","velapaw_pedestal_x1","velapaw_cam_pod_x1"]:
    v,bb=stats(f+".stl")
    print(f"{f:32s} {v:7.1f} cm3   bbox {bb[0]:.0f} x {bb[1]:.0f} x {bb[2]:.0f} mm")
EOF

