1328	
1329	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
1330	      audinfo("Transferring apb=%p, size=%d inflight=%d\n",
1331	              apb, apb->nbytes, priv->inflight);
1332	
1333	      /* Increment the number of buffers in-flight before sending in order
1334	       * to avoid a possible race condition.
1335	       */
1336	
1337	      flags = enter_critical_section();
1338	      priv->inflight++;
1339	      leave_critical_section(flags);
1340	
1341	      /* Send the entire audio buffer via I2S. What is a reasonable timeout
1342	       * to use? This would depend on the bit rate and size of the buffer.
1343	       *
1344	       * Samples in the buffer (samples):
1345	       *   = buffer_size * 8 / bpsamp
1346	       * Sample rate (samples/second):
1347	       *   = samplerate * nchannels
1348	       * Expected transfer time (seconds):
1349	       *   = (buffer_size * 8) / bpsamp / samplerate
1350	       *
1351	       * We will set the timeout about twice that.
1352	       *
1353	       * NOTES:
1354	       * - The multiplier of 8 becomes 16000 for 2x and units of
1355	       *   milliseconds.
1356	       * - 16000 is a approximately 16384 (1 << 14).
1357	       *   So this can be simplifies to (milliseconds):
1358	       *
1359	       *   = (buffer_size << 14) / bpsamp / samplerate
1360	       */
1361	
1362	      timeout = MSEC2TICK(((uint32_t)(apb->nbytes - apb->curbyte) << 14) /
1363	                          (uint32_t)priv->samprate / (uint32_t)priv->bpsamp);
1364	
1365	      if (priv->audio_mode == ES_MODULE_DAC)
1366	        {
1367	          ret = I2S_SEND(priv->i2s, apb, es8311_processdone,
1368	                         priv, timeout);
1369	        }
1370	      else
1371	        {
1372	          ret = I2S_RECEIVE(priv->i2s, apb, es8311_processdone,
1373	                            priv, timeout);
1374	        }
1375	
1376	      if (ret < 0)
1377	        {
1378	          auderr("I2S transfer failed: %d\n", ret);
1379	          break;
1380	        }
1381	    }
1382	
1383	  nxmutex_unlock(&priv->pendlock);
1384	  return ret;
1385	}
