1264	  /* When the transfer was started, the active buffer containers were removed
1265	   * from the rx.pend queue and saved in the rx.act queue. We get here when
1266	   * the DMA is finished.
1267	   *
1268	   * In any case, the buffer containers in rx.act will be moved to the end
1269	   * of the rx.done queue and rx.act will be emptied before this worker is
1270	   * started.
1271	   *
1272	   */
1273	
1274	  i2sinfo("rx.act.head=%p rx.done.head=%p\n",
1275	          priv->rx.act.head, priv->rx.done.head);
1276	
1277	  /* Process each buffer in the rx.done queue */
1278	
1279	  while (sq_peek(&priv->rx.done) != NULL)
1280	    {
1281	      /* Remove the buffer container from the rx.done queue.  NOTE that
1282	       * interrupts must be disabled to do this because the rx.done queue is
