1291	
1292	      bfcontainer->apb->nbytes = 0;
1293	
1294	      while (dmadesc != NULL && (dmadesc->ctrl & ESP32S3_DMA_CTRL_EOF))
1295	        {
1296	          bfcontainer->apb->nbytes +=
1297	              (dmadesc->ctrl >> ESP32S3_DMA_CTRL_DATALEN_S) &
1298	              ESP32S3_DMA_CTRL_DATALEN_V;
1299	          dmadesc = dmadesc->next;
1300	        }
1301	
1302	      /* Perform the RX transfer done callback */
1303	
1304	      DEBUGASSERT(bfcontainer && bfcontainer->callback);
1305	
1306	      if (priv->streaming == false)
1307	        {
1308	          bfcontainer->apb->flags |= AUDIO_APB_FINAL;
1309	        }
