import io, sys
p = "nuttx/arch/xtensa/src/esp32s3/esp32s3_i2s.c"
s = io.open(p, encoding="utf-8").read()

old = """      if (priv->config->audio_std_mode == I2S_TDM_PCM)
        {
          modifyreg32(I2S_RX_CONF1_REG(priv->config->port),
                      I2S_RX_TDM_WS_WIDTH_M,
                      FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH,
                      priv->data_width - 1));
        }
      else
        {
          modifyreg32(I2S_RX_CONF1_REG(priv->config->port),
                      I2S_RX_TDM_WS_WIDTH_M,
                      FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH, 1));
        }
    }
"""

new = """      /* VelaPaw patch #20a: upstream has the PCM / non-PCM branches
       * swapped for RX -- compare the TX block above.  Standard I2S needs
       * a WS half period of data_width bit clocks; PCM needs a one-clock
       * pulse.  Swapped, the RX front end hunted for a 2-BCLK frame while
       * TX generated a 32-BCLK one, so RX never assembled a sample and the
       * GDMA sat armed with DATALEN=0 and INFIFO_UDF_L1 set.
       */

      if (priv->config->audio_std_mode == I2S_TDM_PCM)
        {
          modifyreg32(I2S_RX_CONF1_REG(priv->config->port),
                      I2S_RX_TDM_WS_WIDTH_M,
                      FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH, 1));
        }
      else
        {
          modifyreg32(I2S_RX_CONF1_REG(priv->config->port),
                      I2S_RX_TDM_WS_WIDTH_M,
                      FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH,
                      priv->data_width - 1));
        }

      /* VelaPaw patch #20b: the TX branch pulses I2S_TX_UPDATE to promote
       * these fields into the I2S clock domain; the RX branch never pulsed
       * I2S_RX_UPDATE.  Masked today because i2s_rxdatawidth() brackets
       * this in rx_channel_stop/start, but it must not depend on that.
       */

      modifyreg32(I2S_RX_CONF_REG(priv->config->port), 0, I2S_RX_UPDATE);
    }
"""

n = s.count(old)
if n != 1:
    sys.stderr.write("ABORT: anchor #20 matched %d times\\n" % n)
    sys.exit(1)

io.open(p, "w", encoding="utf-8", newline="\\n").write(s.replace(old, new))
sys.stdout.write("OK: VelaPaw patch #20a + #20b\\nWROTE %s\\n" % p)
