1	/****************************************************************************
2	 * VelaPaw - feeder HAL: real servo backend (ESP32-S3 LEDC/PWM on GPIO43)
3	 *
4	 * The PWM itself lives in the board file (it owns the LEDC registers; the
5	 * camera's XCLK already uses ch0/timer0, so the servo takes ch1/timer1 @50Hz).
6	 * Here we only bridge the app API to it.
7	 *
8	 * IMPORTANT: board_feeder_dispense() SLEEPS while the gate is held open
9	 * (grams x SERVO_MS_PER_GRAM, e.g. ~1.8 s for 15 g). Calling that from the UI
10	 * task would freeze the screen + camera -- the same class of bug as a blocking
11	 * printf. So we run it on a detached worker thread and return immediately;
12	 * the UI keeps rendering while the food drops.
13	 ****************************************************************************/
14	
15	#include <stdio.h>
16	#include <stdint.h>
17	#include <pthread.h>
18	
19	#include "hal/feeder.h"
20	
21	/* Provided by the board (nuttx/boards/.../esp32s3_st7789.c) */
22	extern void board_feeder_init(void);
23	extern int  board_feeder_dispense(int grams);
24	
25	static void *dispense_thread(void *arg)
26	{
27	  int grams = (int)(intptr_t)arg;
28	  board_feeder_dispense(grams);
29	  return NULL;
30	}
31	
32	int velapaw_feeder_init(void)
33	{
34	  /* The board already inits the servo at boot (board_lcd_initialize), so this
35	   * is a no-op; kept so the HAL contract is unchanged. */
36	  return 0;
37	}
38	
39	int velapaw_feeder_dispense(int grams)
40	{
41	  pthread_t th;
42	  pthread_attr_t attr;
43	
44	  if (grams <= 0)
45	    {
46	      return -1;
47	    }
48	
49	  pthread_attr_init(&attr);
50	  pthread_attr_setstacksize(&attr, 2048);
51	  if (pthread_create(&th, &attr, dispense_thread,
52	                     (void *)(intptr_t)grams) != 0)
53	    {
54	      pthread_attr_destroy(&attr);
55	      return -1;
56	    }
57	  pthread_detach(th);
58	  pthread_attr_destroy(&attr);
59	
60	  printf("    [feeder] servo dispensing %d g (async)\n", grams);
61	  return 0;
62	}
