#!/usr/bin/env python3
"""Patch #29 -- restore DAC volume, add an objective mic level meter."""

import os
import sys

HOME = os.path.expanduser("~")
NUTTX = os.path.join(HOME, "openvela", "nuttx")
I2SC = os.path.join(NUTTX, "arch", "xtensa", "src", "esp32s3", "esp32s3_i2s.c")

ANCHOR = "/* Perform the RX transfer done callback */"

PROBE = '''      /* VelaPaw patch #29: an open-air mic/speaker loopback cannot tell
       * us whether the ADC data is clean -- acoustic feedback dominates.
       * Report peak and mean |sample| over the captured buffer instead,
       * every 8th buffer to keep the console quiet.  Thread context, so
       * syslog() is safe here.
       */

      {
        static uint32_t vp_seq = 0;

        if ((vp_seq++ & 7) == 0)
          {
            int16_t *vs = (int16_t *)bfcontainer->apb->samp;
            uint32_t vn = bfcontainer->apb->nbytes / 2;
            uint32_t vi;
            int32_t  vpeak = 0;
            uint64_t vsum = 0;

            for (vi = 0; vi < vn; vi++)
              {
                int32_t vv = vs[vi];

                if (vv < 0)
                  {
                    vv = -vv;
                  }

                if (vv > vpeak)
                  {
                    vpeak = vv;
                  }

                vsum += (uint32_t)vv;
              }

            syslog(LOG_ERR, "VP: mic n=%" PRIu32 " peak=%" PRId32
                            " mean=%" PRIu32 "\\n",
                   vn, vpeak, vn ? (uint32_t)(vsum / vn) : 0);
          }
      }

'''


def set_config(path, key, value):
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.read().splitlines(True)
    if len(lines) < 200:
        print("REFUSE: %s has only %d lines" % (path, len(lines)))
        return False
    want = "%s=%s\n" % (key, value)
    out, seen = [], False
    for ln in lines:
        if ln.startswith(key + "="):
            if not seen:
                out.append(want)
                seen = True
            continue
        out.append(ln)
    if not seen:
        for idx, ln in enumerate(out):
            if ln.startswith("CONFIG_ESP32S3"):
                out.insert(idx, want)
                seen = True
                break
        if not seen:
            out.append(want)
    tmp = path + ".new"
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.writelines(out)
    os.replace(tmp, path)
    print("OK: %s=%s" % (key, value))
    return True


def add_meter(path):
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as fh:
        src = fh.read()
    if len(src) < 50000:
        print("REFUSE: %s is only %d bytes" % (path, len(src)))
        return False
    if "VP: mic " in src:
        print("OK: mic meter already present")
        return True
    if "I2S_RX_MONO_M" not in src:
        print("REFUSE: patch #28 not present -- wrong tree?")
        return False
    n = src.count(ANCHOR)
    if n != 1:
        print("REFUSE: anchor appears %d times, expected 1" % n)
        return False
    at = src.find(ANCHOR)
    ls = src.rfind("\n", 0, at) + 1
    src = src[:ls] + PROBE + src[ls:]
    tmp = path + ".new"
    with open(tmp, "w", encoding="utf-8", errors="surrogateescape") as fh:
