285	/* Build the 49x40 feature map.  One interpreter invocation per frame -- the
286	 * frontend graph is stateful across calls (spectral subtraction and PCAN both
287	 * carry noise estimates forward), so frames MUST be fed in time order and the
288	 * interpreter must not be rebuilt between them.
289	 */
290	
291	static int kws_generate_features(const int16_t *audio, size_t nsamples)
292	{
293	  TfLiteTensor *input  = g_frontend->input(0);
294	  TfLiteTensor *output = g_frontend->output(0);
295	  size_t remaining     = nsamples;
296	  int frame            = 0;
297	
298	  while (remaining >= VELAPAW_KWS_FRAME_SAMPLES &&
299	         frame < VELAPAW_KWS_FEATURE_COUNT)
300	    {
301	      std::copy_n(audio, VELAPAW_KWS_FRAME_SAMPLES,
302	                  tflite::GetTensorData<int16_t>(input));
303	
304	      if (g_frontend->Invoke() != kTfLiteOk)
305	        {
306	          printf("kws: frontend Invoke failed at frame %d\n", frame);
307	          return -EIO;
308	        }
309	
310	      std::copy_n(tflite::GetTensorData<int8_t>(output),
311	                  VELAPAW_KWS_FEATURE_SIZE, g_features[frame]);
312	
313	      frame     += 1;
314	      audio     += VELAPAW_KWS_STRIDE_SAMPLES;
315	      remaining -= VELAPAW_KWS_STRIDE_SAMPLES;
316	    }
317	
318	  if (frame != VELAPAW_KWS_FEATURE_COUNT)
319	    {
320	      printf("kws: only %d/%d frames from %u samples\n",
321	             frame, VELAPAW_KWS_FEATURE_COUNT, (unsigned)nsamples);
322	      return -EINVAL;
323	    }
324	
325	  return 0;
326	}
