363	int velapaw_kws_classify(const int16_t *audio, size_t nsamples,
364	                         struct velapaw_kws_result_s *result)
365	{
366	  uint32_t t0;
367	  uint32_t t1;
368	  uint32_t t2;
369	  int ret;
370	  int i;
371	  int best;
372	
373	  if (audio == nullptr || result == nullptr)
374	    {
375	      return -EINVAL;
376	    }
377	
378	  if (!g_ready)
379	    {
380	      ret = velapaw_kws_init();
381	      if (ret < 0)
382	        {
383	          return ret;
384	        }
385	    }
386	
387	  if (nsamples < (size_t)VELAPAW_KWS_MIN_SAMPLES)
388	    {
389	      printf("kws: %u samples, need at least %d\n",
390	             (unsigned)nsamples, VELAPAW_KWS_MIN_SAMPLES);
391	      return -EINVAL;
392	    }
393	
394	  memset(result, 0, sizeof(*result));
395	
396	  t0  = kws_now_ms();
397	  ret = kws_generate_features(audio, nsamples);
398	  if (ret < 0)
399	    {
400	      return ret;
401	    }
402	
403	  t1 = kws_now_ms();
404	
405	  TfLiteTensor *input  = g_classifier->input(0);
406	  TfLiteTensor *output = g_classifier->output(0);
407	
408	  std::copy_n(&g_features[0][0],
409	              VELAPAW_KWS_FEATURE_COUNT * VELAPAW_KWS_FEATURE_SIZE,
410	              tflite::GetTensorData<int8_t>(input));
411	
412	  if (g_classifier->Invoke() != kTfLiteOk)
413	    {
414	      printf("kws: classifier Invoke failed\n");
415	      return -EIO;
416	    }
417	
418	  t2 = kws_now_ms();
419	
420	  /* Dequantise: the graph ends in Softmax, so these sum to ~1.0. */
421	
422	  best = 0;
423	  for (i = 0; i < VELAPAW_KWS_CATEGORIES; i++)
424	    {
425	      result->scores[i] =
426	        (tflite::GetTensorData<int8_t>(output)[i] - output->params.zero_point) *
427	        output->params.scale;
428	
429	      if (result->scores[i] > result->scores[best])
430	        {
431	          best = i;
432	        }
433	    }
434	
435	  result->label      = best;
436	  result->score      = result->scores[best];
437	  result->feature_ms = t1 - t0;
438	  result->infer_ms   = t2 - t1;
439	
440	  return 0;
441	}
